const input = $json;

if (!input.analysis_run_id) {
  throw new Error(
    'REPORT_INPUT_MISSING_RUN_ID'
  );
}

const analysisRunId = String(input.analysis_run_id);

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(analysisRunId)) {
  throw new Error(
    'REPORT_INPUT_INVALID_RUN_ID'
  );
}

return [
  {
    json: {
      analysis_run_id: analysisRunId,
      trigger_context: {
        completion_claimed: input.completion_claimed ?? null,
        barrier_ready: input.barrier_ready ?? null,
        final_count: input.final_count ?? null,
        finalization_state: input.finalization_state ?? null
      }
    }
  }
];

const input = $json;
const snapshot = input.snapshot ?? {};
const run = snapshot.analysis_run;

if (!run) {
  throw new Error('REPORT_RUN_NOT_FOUND');
}

if (String(run.id) !== String(input.analysis_run_id)) {
  throw new Error('REPORT_SNAPSHOT_RUN_ID_MISMATCH');
}

if (run.status !== 'completed') {
  throw new Error(
    `REPORT_RUN_NOT_COMPLETED: ${run.status}`
  );
}

const fields = snapshot.field_results;

if (!Array.isArray(fields)) {
  throw new Error('REPORT_FIELD_RESULTS_MISSING');
}

if (fields.length !== 27) {
  throw new Error(
    `REPORT_FINAL_COUNT_INVALID: expected 27, got ${fields.length}`
  );
}

const indexes = fields.map(field => Number(field.field_index));

if (
  new Set(indexes).size !== 27
  ||
  !indexes.every((index, position) => index === position + 1)
) {
  throw new Error('REPORT_FIELD_INDEXES_INVALID');
}

const keys = fields.map(field => field.field_key);

if (
  keys.some(key => typeof key !== 'string' || key.length === 0)
  ||
  new Set(keys).size !== 27
) {
  throw new Error('REPORT_FIELD_KEYS_INVALID');
}

const invalidCatalog = fields.filter(
  field => field.field_catalog_version !== 'tender_fields_v1'
);

if (invalidCatalog.length > 0) {
  throw new Error('REPORT_FIELD_CATALOG_INVALID');
}

const invalidContract = fields.filter(
  field => field.result_contract_version !== 'tender_field_final_v1'
);

if (invalidContract.length > 0) {
  throw new Error('REPORT_FIELD_CONTRACT_INVALID');
}

const invalidStatus = fields.filter(
  field =>
    !['resolved', 'requires_review', 'not_found'].includes(field.status)
);

if (invalidStatus.length > 0) {
  throw new Error('REPORT_FIELD_STATUS_INVALID');
}

const meta = run.tender_meta ?? {};

return [
  {
    json: {
      analysis_run_id: run.id,
      snapshot,
      field_results: fields,
      readiness: {
        ready: true,
        final_count: fields.length
      },
      procurement: {
        number: meta.tender_number ?? run.tender_number ?? null,
        title: meta.title ?? null,
        platform: meta.platform?.name ?? null,
        platform_url: meta.platform?.url ?? null,
        customer:
          meta.primary_customer?.name ??
          meta.customers?.[0]?.name ??
          null,
        max_price: meta.max_price ?? null,
        currency: meta.currency ?? 'RUB',
        publication_at: meta.publication_at ?? null,
        submission_start_at: meta.submission_start_at ?? null,
        submission_close_at: meta.submission_close_at ?? null,
        documents_count:
          meta.documents_count ??
          snapshot.documents.length,
        okpd2: meta.okpd2 ?? []
      }
    }
  }
];

const input = $json;
const fields = input.field_results;
const procurement = input;


// ============================================================
// Извлечение источника из result_json
// ============================================================

function extractSource(resultJson) {

  if (!resultJson) {
    return null;
  }


  const evidence =
    resultJson?.evidence || [];


  if (!evidence.length) {
    return null;
  }


  const firstEvidence = evidence[0];


  return {

    quote:
      firstEvidence.quote || null,


    document:
      firstEvidence.document?.file_name || null,


    document_id:
      firstEvidence.document?.document_id || null,


    semantic_block_id:
      firstEvidence.semantic_block_id || null,


    page_from:
      firstEvidence.page_from || null,


    page_to:
      firstEvidence.page_to || null,


    sheet_name:
      firstEvidence.sheet_name || null

  };

}


// ============================================================
// Формирование результата
// ============================================================

return [
  {
    json: {

      analysis_run_id:
        procurement.analysis_run_id,


      procurement:
        procurement.procurement,


      fields: fields.map(field => ({

        field_index:
          field.field_index,


        key:
          field.field_key,


        status:
          field.status,


        value:
          field.value_text,


        confidence:
          field.confidence,


        requires_review:
          field.requires_human_review,

        result_json: field.result_json,


        // Новый блок источника
        source:
          extractSource(
            field.result_json
          )

      })),


      statistics: {

        total:
          fields.length,


        resolved:
          fields.filter(
            f => f.status === 'resolved'
          ).length,


        requires_review:
          fields.filter(
            f => f.status === 'requires_review'
          ).length,


        not_found:
          fields.filter(
            f => f.status === 'not_found'
          ).length

      }

    }
  }
];

const input = $json;

if (!input.analysis_run_id) {
  throw new Error('REPORT_MODEL_MISSING_RUN_ID');
}

if (!input.procurement) {
  throw new Error('REPORT_MODEL_MISSING_PROCUREMENT');
}

if (!Array.isArray(input.fields)) {
  throw new Error('REPORT_MODEL_FIELDS_MISSING');
}

if (input.fields.length !== 27) {
  throw new Error(
    `REPORT_MODEL_FIELD_COUNT_INVALID: expected 27, got ${input.fields.length}`
  );
}

const mapping = [
  { field_index: 1, field: 'procurement_subject', label: 'Предмет закупки' },
  { field_index: 2, field: 'nm_price_with_vat', label: 'НМЦ (с НДС)' },
  { field_index: 3, field: 'platform', label: 'Площадка' },
  { field_index: 4, field: 'procedure_type', label: 'Тип процедуры' },
  { field_index: 5, field: 'application_deadline', label: 'Срок окончания приема заявок' },
  { field_index: 6, field: 'application_review_date', label: 'Дата рассмотрения заявок' },
  { field_index: 7, field: 'results_date', label: 'Дата подведения итогов' },
  { field_index: 8, field: 'customer', label: 'Заказчик' },
  { field_index: 9, field: 'customer_contacts', label: 'Контактная информация Заказчика' },
  { field_index: 10, field: 'participation_cost', label: 'Стоимость участия' },
  { field_index: 11, field: 'participation_guarantee', label: 'БГ на участие' },
  { field_index: 12, field: 'evaluation_criteria', label: 'Критерии оценки' },
  { field_index: 13, field: 'delivery_term', label: 'Срок поставки (исполнения)' },
  { field_index: 14, field: 'payment_terms', label: 'Условия оплаты' },
  { field_index: 15, field: 'special_account_or_treasury', label: 'Спецсчет/казна' },
  { field_index: 16, field: 'bank_support', label: 'Банковское сопровождение' },
  { field_index: 17, field: 'government_contract', label: 'Госконтракт' },
  { field_index: 18, field: 'rebidding', label: 'Переторжка' },
  { field_index: 19, field: 'national_regime', label: 'Национальный режим' },
  { field_index: 20, field: 'advance_contract_guarantee', label: 'БГ аванс' },
  { field_index: 21, field: 'warranty_obligations_guarantee', label: 'БГ гарантийные обязательства' },
  { field_index: 22, field: 'licenses_certificates', label: 'Лицензии/сертификаты' },
  { field_index: 23, field: 'required_official_certificates', label: 'Необходимые справки' },
  { field_index: 24, field: 'similar_supply_experience', label: 'Опыт аналогичных поставок' },
  { field_index: 25, field: 'analog_allowed', label: 'Допускается ли аналог' },
  { field_index: 26, field: 'analog_definition', label: 'Что считается аналогом' },
  { field_index: 27, field: 'application_documents', label: 'Состав заявки' }
];

const fieldsByIndex = new Map();
const fieldsByKey = new Set();

for (const field of input.fields) {
  const fieldIndex = Number(field.field_index);
  const definition = mapping[fieldIndex - 1];

  if (!definition || fieldsByIndex.has(fieldIndex)) {
    throw new Error('REPORT_MODEL_FIELD_INDEX_INVALID');
  }

  if (field.key !== definition.field) {
    throw new Error(
      `REPORT_MODEL_FIELD_KEY_MISMATCH: index ${fieldIndex}`
    );
  }

  if (fieldsByKey.has(field.key)) {
    throw new Error(
      `REPORT_MODEL_FIELD_KEY_DUPLICATE: ${field.key}`
    );
  }

  if (!['resolved', 'requires_review', 'not_found'].includes(field.status)) {
    throw new Error(
      `REPORT_MODEL_STATUS_INVALID: ${field.key}`
    );
  }

  if (field.result_json === undefined || field.result_json === null) {
    throw new Error(
      `REPORT_MODEL_RESULT_JSON_MISSING: ${field.key}`
    );
  }

  if (
    field.status === 'resolved'
    &&
    (field.value === undefined || field.value === null)
  ) {
    throw new Error(
      `REPORT_MODEL_RESOLVED_VALUE_MISSING: ${field.key}`
    );
  }

  if (
    field.status === 'not_found'
    &&
    field.value !== null
    &&
    field.value !== undefined
  ) {
    throw new Error(
      `REPORT_MODEL_NOT_FOUND_VALUE_INVALID: ${field.key}`
    );
  }

  const requiresReview = field.status === 'requires_review';

  if (Boolean(field.requires_review) !== requiresReview) {
    throw new Error(
      `REPORT_MODEL_REVIEW_FLAG_MISMATCH: ${field.key}`
    );
  }

  fieldsByIndex.set(fieldIndex, field);
  fieldsByKey.add(field.key);
}

const reportFields = mapping.map(definition => {
  const field = fieldsByIndex.get(definition.field_index);

  return {
    field_index: definition.field_index,
    field: definition.field,
    label: definition.label,
    status: field.status,
    value: field.value ?? null,
    requires_review: field.status === 'requires_review',
    result_json: field.result_json
  };
});

const statistics = {
  total: reportFields.length,
  resolved: reportFields.filter(field => field.status === 'resolved').length,
  requires_review: reportFields.filter(
    field => field.status === 'requires_review'
  ).length,
  not_found: reportFields.filter(
    field => field.status === 'not_found'
  ).length
};

if (
  input.statistics
  &&
  (
    input.statistics.total !== statistics.total
    ||
    input.statistics.resolved !== statistics.resolved
    ||
    input.statistics.requires_review !== statistics.requires_review
    ||
    input.statistics.not_found !== statistics.not_found
  )
) {
  throw new Error('REPORT_MODEL_STATISTICS_MISMATCH');
}

return [
  {
    json: {
      analysis_run_id: input.analysis_run_id,
      procurement: {
        number: input.procurement.number ?? null,
        subject:
          input.procurement.subject ??
          input.procurement.title ??
          null,
        customer: input.procurement.customer ?? null,
        platform: input.procurement.platform ?? null,
        price:
          input.procurement.price ??
          input.procurement.max_price ??
          null,
        publication_at: input.procurement.publication_at ?? null
      },
      statistics,
      report_fields: reportFields
    }
  }
];

// ============================================================
// Подготовка структуры отчёта закупки
// ============================================================


// Получаем данные из предыдущих нод
const input = $json;


// ------------------------------------------------------------
// 1. Проверка входных данных
// ------------------------------------------------------------

if (!input.analysis_run_id) {
  throw new Error(
    'Нет analysis_run_id для генерации отчёта'
  );
}

if (!input.procurement) {
  throw new Error(
    'Нет данных закупки'
  );
}

if (!Array.isArray(input.report_fields)) {
  throw new Error(
    'Нет report_fields'
  );
}


// ------------------------------------------------------------
// 2. Словарь нормальных названий полей
// Пока здесь ручной mapping.
// Позже вынесем в таблицу field_catalog.
// ------------------------------------------------------------

const fieldTitles = {

  nm_price_with_vat:
    'Начальная максимальная цена / цена с НДС',

  evaluation_criteria:
    'Критерии оценки заявки',

  special_account_or_treasury:
    'Специальный счёт / казначейское сопровождение',

  bank_support:
    'Банковское сопровождение',

  rebidding:
    'Переторжка',

  advance_contract_guarantee:
    'Обеспечение аванса',

  similar_supply_experience:
    'Опыт аналогичных поставок',

  analog_allowed:
    'Допустимость аналогов',

  analog_definition:
    'Описание требований к аналогам',

  application_documents:
    'Документы для подачи заявки'

};


// ------------------------------------------------------------
// 3. Группы отчёта
// ------------------------------------------------------------

const sections = {};

const missingFields = [];
const reviewFields = [];
const resolvedFields = [];


// ------------------------------------------------------------
// 4. Обработка полей
// ------------------------------------------------------------

for (const field of input.report_fields) {

  const preparedField = {

    key: field.key,

    title:
      field.title !== field.key
        ? field.title
        : fieldTitles[field.key] || field.key,

    value: field.value,

    status: field.status,

    confidence: field.confidence,

    requires_review:
      field.requires_review === true

  };


  // группировка по разделам

  const sectionName =
    field.section || 'Прочее';


  if (!sections[sectionName]) {
    sections[sectionName] = [];
  }


  sections[sectionName].push(preparedField);



  // статистика

  if (field.status === 'resolved') {

    resolvedFields.push(preparedField);

  }


  if (field.status === 'requires_review') {

    reviewFields.push(preparedField);

  }


  if (field.status === 'not_found') {

    missingFields.push(preparedField);

  }

}


// ------------------------------------------------------------
// 5. Финальный объект отчёта
// ------------------------------------------------------------


return [

  {

    json: {

      analysis_run_id:
        input.analysis_run_id,


      report: {


        // -------------------------
        // Общая информация
        // -------------------------

        procurement: {

          number:
            input.procurement.number,

          title:
            input.procurement.title,

          platform:
            input.procurement.platform,

          platform_url:
            input.procurement.platform_url,

          customer:
            input.procurement.customer,

          max_price:
            input.procurement.max_price,

          currency:
            input.procurement.currency,

          publication_at:
            input.procurement.publication_at,

          deadline:
            input.procurement.submission_close_at

        },


        // -------------------------
        // Основные поля
        // -------------------------

        sections,


        // -------------------------
        // Контроль качества
        // -------------------------

        quality: {

          total:
            input.statistics.total,

          resolved:
            resolvedFields.length,

          requires_review:
            reviewFields.length,

          not_found:
            missingFields.length

        },


        // -------------------------
        // Что требует внимания
        // -------------------------

        review_items:
          reviewFields,


        // -------------------------
        // Что не найдено
        // -------------------------

        missing_items:
          missingFields


      }

    }

  }

];

const report = $json.report;


// ============================================================
// 1. Форматирование дат
// ============================================================

function formatDate(date) {

  if (!date) return null;

  return new Date(date).toLocaleString(
    'ru-RU',
    {
      timeZone: 'Europe/Moscow',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }
  );

}


// ============================================================
// 2. Форматирование цены
// ============================================================

function formatPrice(value) {

  if (value === null || value === undefined) {
    return null;
  }

  return `${Number(value).toLocaleString('ru-RU')} ₽`;

}


// ============================================================
// 3. Поля, которые не нужно показывать клиенту,
// если они просто не найдены
// ============================================================

const hiddenMissingFields = [
  'rebidding',
  'bank_support',
  'special_account_or_treasury'
];


// Поля с датами, которые нужно форматировать
const dateFields = [
  'application_deadline',
  'application_review_date',
  'results_date'
];


// ============================================================
// 4. Подготовка проблемных полей
// ============================================================

const attentionItems = report.review_items.map(item => {

  let comment = null;

  let value = item.value;


  switch (item.key) {

    case 'nm_price_with_vat':

      value = formatPrice(
        report.procurement.max_price
      );

      comment =
        'Цена закупки найдена в данных площадки, но наличие НДС и назначение суммы как НМЦК требуют проверки по документам.';

      break;


    case 'government_contract':

      comment =
        'Обнаружено упоминание реестра договоров, но прямое подтверждение статуса государственного контракта отсутствует.';

      break;


    case 'warranty_obligations_guarantee':

      comment =
        'Обнаружены гарантийные обязательства по качеству товара. Наличие обеспечения гарантийных обязательств не подтверждено.';

      break;


    default:

      comment =
        'Требуется дополнительная проверка.';

  }


  return {

    key: item.key,

    name: item.title,

    value:
      value || 'Не определено',

    comment,

    status: item.status

  };

});


// ============================================================
// 5. Подготовка отсутствующих данных
// ============================================================

const missingItems = report.missing_items

  .filter(item =>
    !hiddenMissingFields.includes(item.key)
  )

  .map(item => ({

    key: item.key,

    name: item.title,

    status:
      'Не найдено в доступных документах'

  }));


// ============================================================
// 6. Подготовка разделов
// ============================================================

const sections = Object.entries(report.sections)
.map(([name, fields]) => {


  let sectionName = name;


  if (sectionName === 'Прочее') {

    sectionName =
      'Дополнительные условия';

  }


  return {

    name: sectionName,


    fields: fields.map(field => {


      let value = field.value;


      // НМЦК:
      // берём цену из данных площадки,
      // если документы не подтвердили НДС/назначение суммы

      if (
        field.key === 'nm_price_with_vat'
        &&
        field.status === 'requires_review'
      ) {

        value =
          formatPrice(
            report.procurement.max_price
          );

      }


      // Форматируем даты

      if (
        dateFields.includes(field.key)
        &&
        field.value
      ) {

        value =
          formatDate(field.value);

      }


      // Не найдено

      if (
        field.status === 'not_found'
      ) {

        value =
          'Не найдено';

      }


      // Если нет значения у requires_review

      if (
        field.status === 'requires_review'
        &&
        !value
      ) {

        value =
          'Требует проверки';

      }


      return {

        key:
          field.key,

        name:
          field.title,

        value,

        status:
          field.status

      };

    })

  };

});


// ============================================================
// 7. Подготовка шапки отчёта
// ============================================================

const procurement = {

  ...report.procurement,

  max_price_formatted:
    formatPrice(
      report.procurement.max_price
    ),

  publication_at_formatted:
    formatDate(
      report.procurement.publication_at
    ),

  deadline_formatted:
    formatDate(
      report.procurement.deadline
    )

};


// ============================================================
// 8. Финальный объект
// ============================================================

return [

  {

    json: {

      analysis_run_id:
        $json.analysis_run_id,


      report_ready: true,


      report_data: {

        procurement,


        sections,


        attention_items:
          attentionItems,


        missing_items:
          missingItems,


        quality:
          report.quality

      }

    }

  }

];

const report = $json.report_data;


// ============================================================
// Вспомогательные функции
// ============================================================

function escapeMarkdown(value) {

  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/\|/g, '\\|');

}


function statusLabel(status) {

  switch (status) {

    case 'resolved':
      return '✅ Подтверждено';

    case 'requires_review':
      return '⚠️ Требует проверки';

    case 'not_found':
      return '❌ Не найдено';

    default:
      return '';

  }

}


// Длинные поля лучше выводить отдельными блоками
function isLongValue(value) {

  if (!value) return false;

  return value.length > 180;

}


// ============================================================
// Заголовок
// ============================================================

let markdown = '';

markdown += `# Анализ закупки №${report.procurement.number}\n\n`;

markdown += `## Основная информация\n\n`;

markdown += `**Предмет закупки:** ${escapeMarkdown(report.procurement.title)}\n\n`;

markdown += `**Заказчик:** ${escapeMarkdown(report.procurement.customer)}\n\n`;

markdown += `**Электронная площадка:** ${escapeMarkdown(report.procurement.platform)}\n\n`;

markdown += `**НМЦК по данным площадки:** ${report.procurement.max_price_formatted}\n\n`;

markdown += `**Дата публикации:** ${report.procurement.publication_at_formatted}\n\n`;

markdown += `**Срок подачи заявки:** ${report.procurement.deadline_formatted}\n\n`;

markdown += `---\n\n`;


// ============================================================
// Разделы
// ============================================================


for (const section of report.sections) {


  // Общую информацию уже вывели выше

  if (section.name === 'Общая информация') {
    continue;
  }


  markdown += `## ${section.name}\n\n`;


  const tableFields = [];

  const longFields = [];


  for (const field of section.fields) {


    if (
      isLongValue(field.value)
      &&
      field.status === 'resolved'
    ) {

      longFields.push(field);

    } else {

      tableFields.push(field);

    }

  }


  // Таблица коротких значений

  if (tableFields.length > 0) {

    markdown += `| Поле | Значение | Статус |\n`;

    markdown += `|---|---|---|\n`;


    for (const field of tableFields) {

      markdown +=
        `| ${escapeMarkdown(field.name)} | ${escapeMarkdown(field.value)} | ${statusLabel(field.status)} |\n`;

    }


    markdown += `\n`;

  }



  // Длинные значения отдельными блоками

  for (const field of longFields) {

    markdown += `### ${field.name}\n\n`;

    markdown += `${escapeMarkdown(field.value)}\n\n`;

    markdown += `Статус: ${statusLabel(field.status)}\n\n`;

  }


}


// ============================================================
// Требует внимания
// ============================================================


if (
  report.attention_items &&
  report.attention_items.length > 0
) {

  markdown += `## ⚠️ Требует внимания\n\n`;


  for (const item of report.attention_items) {

    markdown += `### ${item.name}\n\n`;

    markdown += `**Значение:** ${escapeMarkdown(item.value)}\n\n`;

    markdown += `**Почему требует проверки:** ${escapeMarkdown(item.comment)}\n\n`;

  }

}


// ============================================================
// Не найдено
// ============================================================


const importantMissing = [

  'Дата рассмотрения заявок',

  'Дата подведения итогов',

  'Критерии оценки заявки',

  'Документы для подачи заявки',

  'Опыт аналогичных поставок'

];


const filteredMissing =
  report.missing_items.filter(item =>
    importantMissing.includes(item.name)
  );


if (filteredMissing.length > 0) {

  markdown += `## Не найдено в документах\n\n`;


  for (const item of filteredMissing) {

    markdown += `- ${escapeMarkdown(item.name)}\n`;

  }


  markdown += `\n`;

}


// ============================================================
// Статистика
// ============================================================


markdown += `## Статистика анализа\n\n`;

markdown += `- Всего проверено полей: ${report.quality.total}\n`;

markdown += `- Подтверждено: ${report.quality.resolved}\n`;

markdown += `- Требуют проверки: ${report.quality.requires_review}\n`;

markdown += `- Не найдено: ${report.quality.not_found}\n`;


// ============================================================
// Output
// ============================================================


return [
  {
    json: {

      analysis_run_id:
        $json.analysis_run_id,


      filename:
        `Анализ закупки_${report.procurement.number}.md`,


      markdown

    }
  }
];

const markdown = $json.markdown;

const filename = $json.filename || 'report.md';

return [
  {
    json: {
      filename
    },
    binary: {
      data: {
        data: Buffer.from(markdown, 'utf8').toString('base64'),
        mimeType: 'text/markdown',
        fileName: filename
      }
    }
  }
];

// ============================================================
// Добавление источников и доказательств к результатам анализа
// ============================================================


// Все входные items = результаты полей
const fields = items.map(item => item.json);


// ============================================================
// Функция извлечения evidence
// ============================================================

function extractSources(resultJson) {

  if (!resultJson) {
    return [];
  }


  const evidence =
    resultJson.evidence || [];


  return evidence.map(e => {

    return {

      document:
        e.document?.file_name || null,


      quote:
        e.quote || null,


      page:
        e.page_from || null,


      semantic_block:
        e.semantic_block_id || null

    };

  });

}


// ============================================================
// Добавляем источники
// ============================================================

const enrichedFields = fields.map(field => {


  let sources = [];


  try {

    sources =
      extractSources(
        field.result_json
      );

  } catch (error) {

    sources = [];

  }



  return {

    ...field,


    sources

  };


});


// ============================================================
// Возвращаем единый объект
// ============================================================

return [

  {

    json: {

      analysis_run_id:
        fields[0]?.analysis_run_id,


      fields:
        enrichedFields

    }

  }

];
